interface Clock {
  now(): Date;
}

class SystemClock implements Clock {
  now(): Date {
    return new Date();
  }
}

class Counter {
  #value = 0;
  inc(by: number = 1): number {
    this.#value += by;
    return this.#value;
  }
  get value(): number {
    return this.#value;
  }
}

const c = new Counter();
c.inc(2);
